    /// <summary>Save a smart-charging schedule and wait for the change to settle.</summary>
    /// <param name="vin">The vehicle identification number.</param>
    /// <param name="startChargeTime">When charging starts, <c>HH:MM</c>.</param>
    /// <param name="endChargeTime">When charging ends, <c>HH:MM</c>, or <c>full</c>.</param>
    /// <param name="chargeWay"><c>s</c> (single), <c>e</c> (every day) or weekday indices.</param>
    /// <param name="enabled">Whether the schedule is active. Default <c>true</c>.</param>
    /// <param name="mqttTimeout">
    /// Seconds to wait for the MQTT push; the config's <c>MqttTimeout</c> when null.
    /// </param>
    /// <param name="pollAttempts">HTTP polls after the MQTT wait. Default <c>10</c>.</param>
    /// <param name="pollInterval">
    /// Seconds slept before each poll; null for the official app's 33 s ladder (1, 0.5, 0.5, 2, 2, 2,
    /// 5, 5, 5, 10).
    /// </param>
    public async Task<ChargeChangeResult> SaveChargingScheduleAsync(
        string vin,
        string startChargeTime,
        string endChargeTime,
        string chargeWay,
        bool? enabled = null,
        double? mqttTimeout = null,
        long? pollAttempts = null,
        double? pollInterval = null)
    {
        var args = Invoker.NewArgs()
            .Add("vin", vin)
            .Add("start_charge_time", startChargeTime)
            .Add("end_charge_time", endChargeTime)
            .Add("charge_way", chargeWay)
            .Add("enabled", enabled)
            .Add("mqtt_timeout", mqttTimeout)
            .Add("poll_attempts", pollAttempts)
            .Add("poll_interval", pollInterval);
        return await Invoker.CallAsync<ChargeChangeResult>(
            "save_charging_schedule",
            args,
            ChargeChangeResultJson.ReadValue).ConfigureAwait(false);
    }

